preConditionHook:
// SUPPORT BREAK, RESISTANCE, RECLAIM (Brian's notes ON-43, #43, p.49). A
// support level made of wicks -- the I2 zone (below) of the minSupportTouches
// most recent swingStrength-bar swing lows in the last pivotLookback bars, per
// Brian's resolution (2026-11-05: a cluster of wick lows built like I2, not
// the most recent swing low); the level L is its bottom, and no bar from the
// oldest of those wicks to bar 1 closed more than closeMarginAtr ATRs below
// it (default 0: "no closes below"). A close below L starts the setup. While
// it runs, price must not go more than maxDepthAtr ATRs below L, nor stay
// below more than maxBarsBelow bars; each bar whose high comes within tolAtr
// ATRs of L from below and closes back below it is a resistance touch. The
// first close back above L ends the setup and is a long if at least
// minResistanceTouches touches came first; a reclaim with fewer touches, a
// deep move or a timeout resets it, and the next bar may start a new one. The
// short is the note's "second example": the mirror at a resistance cluster of
// swing highs, broken upward, tested from above, lost again.
//
// State per side: stL 0 waiting for the break, 1 below the level. wasL holds
// the state at the start of the bar, so the break bar does not count itself
// as a test. The level is latched at the break; the ATR bounds read the
// current ATR. Both sides run independently.
//
//
// I2 SUPPORT ZONE (Brian's indicator 20250116.1, settled 2026-11-05), inlined.
// A support zone is M (minSupportTouches) CONSECUTIVE swing lows (consecutive in the swing-low
// sequence) of strength S (swingStrength), non-alternating, that all lie within W (zoneWidthAtr) ATRs of each
// other (max - min <= W x ATR) and whose POPULATION standard deviation is at
// most K (zoneStdAtr) ATRs -- Brian's spread test, replacing the identically-zero
// horizontal-line R^2. Bottom = the lowest of them, top = the highest. A close
// more than a margin (closeMarginAtr) of ATRs below the bottom kills it. Resistance mirrors:
// swing highs, killed by a close more than the margin above the top. Sums run
// newest-first, mean first and squared deviations second (two passes). The
// members are found by re-scanning the window, because EasyLanguage arrays
// have no row in the register. Pivot test hand-rolled as in SwingPivotTarget
// (EL_Swing_Probe.txt): AT OR ABOVE the S OLDER bars, STRICTLY ABOVE the S
// NEWER bars (the smaller index), lag exactly S; the low side mirrors. No
// Break -- not a registered word.
//
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and updated
// thereafter as TWO statements -- EL evaluates S[1] + in - out left to right,
// and folding it to S += in - out rounds differently. The local counter is
// atrLen, not the input.
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLength;
tolPx = tolAtr * atrVal;
depthPx = maxDepthAtr * atrVal;
fireL = false;
fireS = false;
wasL = stL;
wasS = stS;
// long: support cluster of swing lows
if (wasL == 0) {
    zN = 0;
    zMin = 0.0;
    zMax = 0.0;
    zSum = 0.0;
    zOld = 0;
    for (int jj = (int)swingStrength; jj <= (int)pivotLookback - 1; ++jj) {
        okP = true;
        for (int kk = jj - (int)swingStrength; kk <= jj - 1; ++kk) {
            if (el_ge(low[jj], low[kk])) okP = false;
        }
        for (int kk = jj + 1; kk <= jj + (int)swingStrength; ++kk) {
            if (el_gt(low[jj], low[kk])) okP = false;
        }
        if (okP && zN < (int)minSupportTouches) {
            zN = zN + 1;
            if (zN == 1) {
                zMin = low[jj];
                zMax = low[jj];
            }
            if (el_lt(low[jj], zMin)) zMin = low[jj];
            if (el_gt(low[jj], zMax)) zMax = low[jj];
            zSum = zSum + low[jj];
            zOld = jj;
        }
    }
    if (zN >= 1 && zN == (int)minSupportTouches) {
        zMu = zSum / zN;
        zSS = 0.0;
        for (int jj = (int)swingStrength; jj <= zOld; ++jj) {
            okP = true;
            for (int kk = jj - (int)swingStrength; kk <= jj - 1; ++kk) {
                if (el_ge(low[jj], low[kk])) okP = false;
            }
            for (int kk = jj + 1; kk <= jj + (int)swingStrength; ++kk) {
                if (el_gt(low[jj], low[kk])) okP = false;
            }
            if (okP) zSS = zSS + (low[jj] - zMu) * (low[jj] - zMu);
        }
        zOk = el_le(zMax - zMin, zoneWidthAtr * atrVal) && el_le(std::sqrt(zSS / zN), zoneStdAtr * atrVal);
        for (int kk = 1; kk <= zOld; ++kk) {
            if (el_lt(close[kk], zMin - closeMarginAtr * atrVal)) zOk = false;
        }
        if (zOk && el_lt(close[0], zMin)) {
            stL = 1;
            lvlL = zMin;
            sinceL = 0;
            resL = 0;
        }
    }
}
if (wasL == 1) {
    sinceL = sinceL + 1;
    doneL = false;
    if (el_lt(low[0], lvlL - depthPx) || sinceL > (int)maxBarsBelow) {
        stL = 0;
        doneL = true;
    }
    if (!doneL && el_gt(close[0], lvlL)) {
        fireL = resL >= (int)minResistanceTouches;
        stL = 0;
        doneL = true;
    }
    if (!doneL && el_ge(high[0], lvlL - tolPx)) resL = resL + 1;
}
// short: resistance cluster of swing highs
if (wasS == 0) {
    zN = 0;
    zMin = 0.0;
    zMax = 0.0;
    zSum = 0.0;
    zOld = 0;
    for (int jj = (int)swingStrength; jj <= (int)pivotLookback - 1; ++jj) {
        okP = true;
        for (int kk = jj - (int)swingStrength; kk <= jj - 1; ++kk) {
            if (el_le(high[jj], high[kk])) okP = false;
        }
        for (int kk = jj + 1; kk <= jj + (int)swingStrength; ++kk) {
            if (el_lt(high[jj], high[kk])) okP = false;
        }
        if (okP && zN < (int)minSupportTouches) {
            zN = zN + 1;
            if (zN == 1) {
                zMin = high[jj];
                zMax = high[jj];
            }
            if (el_lt(high[jj], zMin)) zMin = high[jj];
            if (el_gt(high[jj], zMax)) zMax = high[jj];
            zSum = zSum + high[jj];
            zOld = jj;
        }
    }
    if (zN >= 1 && zN == (int)minSupportTouches) {
        zMu = zSum / zN;
        zSS = 0.0;
        for (int jj = (int)swingStrength; jj <= zOld; ++jj) {
            okP = true;
            for (int kk = jj - (int)swingStrength; kk <= jj - 1; ++kk) {
                if (el_le(high[jj], high[kk])) okP = false;
            }
            for (int kk = jj + 1; kk <= jj + (int)swingStrength; ++kk) {
                if (el_lt(high[jj], high[kk])) okP = false;
            }
            if (okP) zSS = zSS + (high[jj] - zMu) * (high[jj] - zMu);
        }
        zOk = el_le(zMax - zMin, zoneWidthAtr * atrVal) && el_le(std::sqrt(zSS / zN), zoneStdAtr * atrVal);
        for (int kk = 1; kk <= zOld; ++kk) {
            if (el_gt(close[kk], zMax + closeMarginAtr * atrVal)) zOk = false;
        }
        if (zOk && el_gt(close[0], zMax)) {
            stS = 1;
            lvlS = zMax;
            sinceS = 0;
            resS = 0;
        }
    }
}
if (wasS == 1) {
    sinceS = sinceS + 1;
    doneS = false;
    if (el_gt(high[0], lvlS + depthPx) || sinceS > (int)maxBarsBelow) {
        stS = 0;
        doneS = true;
    }
    if (!doneS && el_lt(close[0], lvlS)) {
        fireS = resS >= (int)minResistanceTouches;
        stS = 0;
        doneS = true;
    }
    if (!doneS && el_le(low[0], lvlS + tolPx)) resS = resS + 1;
}
